package main

import "fmt"

func sum(values []int) int {
    results := make(chan int)
    go func() {
        total := 0
        for _, value := range values {
            total += value
        }
        results <- total
    }()
    return <-results
}

func main() {
    fmt.Println(sum([]int{3, -1, 2}))
}
